#!/usr/bin/env bash
set -euo pipefail
ROOT="$(pwd)"
if [[ ! -f "$ROOT/frontend/index.html" || ! -f "$ROOT/backend/api.py" ]]; then
  echo "❌ این فایل را از ریشه پروژه اجرا کن؛ جایی که backend/ و frontend/ قرار دارند."
  exit 1
fi
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$ROOT/.patch_backups/elfo_denim_v3_$STAMP"
mkdir -p "$BACKUP"
for f in frontend/index.html frontend/elfo-intro-v2.css frontend/elfo-intro-v2.js frontend/elfo-intro-v3.css frontend/elfo-intro-v3.js frontend/elfo-walk-v3.png frontend/elfo-puller-v3.png frontend/denim-zip-v3.png; do
  [[ -f "$ROOT/$f" ]] && cp "$ROOT/$f" "$BACKUP/$(basename "$f")" || true
done
echo "✅ Backup: $BACKUP"
rm -f "$ROOT/frontend/elfo-intro-v2.css" "$ROOT/frontend/elfo-intro-v2.js"

cat > "$ROOT/frontend/elfo-intro-v3.css" <<'EOF_CSS'
/* Royal Jeans — Elfo Denim Intro V3 */
html.elfo-intro-active,
html.elfo-intro-active body { overflow: hidden !important; }

#elfoIntroV3 {
  position: fixed; inset: 0; z-index: 2147483000; overflow: hidden;
  direction: ltr; user-select: none; touch-action: none;
  background: #07111b; isolation: isolate; --zip-y: 0px;
}
#elfoIntroV3[hidden] { display: none !important; }

.elfo-v3-reveal { position:absolute; inset:0; z-index:1; pointer-events:none;
  background: radial-gradient(ellipse at 50% 34%,rgba(255,204,102,.22),transparent 24%),linear-gradient(180deg,rgba(6,13,19,.08),rgba(0,0,0,.34)); opacity:.35; }

.elfo-v3-panel { position:absolute; inset:-2px; z-index:5;
  background-image: linear-gradient(90deg,rgba(0,8,15,.08),transparent 18%,transparent 82%,rgba(0,8,15,.08)),url('/static/denim-zip-v3.png?v=3');
  background-position:center; background-repeat:no-repeat; background-size:cover;
  filter:saturate(1.08) contrast(1.055) brightness(.95);
  will-change:clip-path,transform,filter; transition:transform 1050ms cubic-bezier(.70,0,.18,1),filter 620ms ease; }
.elfo-v3-panel::after { content:''; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(ellipse at 50% 12%,rgba(255,255,255,.10),transparent 33%),radial-gradient(ellipse at 50% 108%,rgba(0,0,0,.28),transparent 52%),linear-gradient(112deg,transparent 25%,rgba(255,255,255,.025) 43%,transparent 60%); mix-blend-mode:screen; }
.elfo-v3-left{clip-path:polygon(0 0,50% 0,50% 100%,0 100%)}
.elfo-v3-right{clip-path:polygon(50% 0,100% 0,100% 100%,50% 100%)}
#elfoIntroV3.is-opening .elfo-v3-left{transform:translate3d(-106%,0,0) rotate(-.55deg);filter:brightness(.72)}
#elfoIntroV3.is-opening .elfo-v3-right{transform:translate3d(106%,0,0) rotate(.55deg);filter:brightness(.72)}

.elfo-v3-open-light{position:absolute;z-index:4;top:0;left:50%;width:0;height:var(--zip-y);transform:translateX(-50%);pointer-events:none;
  box-shadow:0 0 18px 5px rgba(255,203,111,.30),0 0 54px 15px rgba(62,168,230,.12);opacity:0;transition:opacity 180ms ease}
#elfoIntroV3.is-pulling .elfo-v3-open-light{opacity:1}
.elfo-v3-vignette{position:absolute;inset:0;z-index:9;pointer-events:none;box-shadow:inset 0 0 170px rgba(0,4,10,.74),inset 0 -80px 110px rgba(0,0,0,.25);transition:opacity 500ms ease}
#elfoIntroV3.is-opening .elfo-v3-vignette{opacity:0}

.elfo-v3-brand{position:absolute;top:22px;left:25px;z-index:14;color:rgba(232,226,201,.60);font:800 9px/1.2 system-ui,sans-serif;letter-spacing:.25em;text-shadow:0 2px 8px rgba(0,0,0,.8);pointer-events:none}
.elfo-v3-brand::before{content:'';display:inline-block;width:21px;height:1px;margin-right:8px;vertical-align:middle;background:rgba(224,181,91,.58)}

.elfo-v3-character{position:absolute;z-index:30;width:clamp(104px,9vw,150px);aspect-ratio:543/724;margin:0;padding:0;border:0;outline:0;background:transparent;cursor:pointer;-webkit-tap-highlight-color:transparent;will-change:transform,opacity}
.elfo-v3-character:focus-visible{outline:2px solid rgba(235,193,99,.95);outline-offset:7px;border-radius:16px}
.elfo-v3-shadow{position:absolute;z-index:0;left:13%;right:13%;bottom:-1.2%;height:6.5%;border-radius:50%;background:rgba(0,0,0,.52);filter:blur(5px);transform-origin:center;will-change:transform,opacity;pointer-events:none}
.elfo-v3-flip{position:absolute;inset:0;z-index:2;transform:scaleX(var(--elfo-face,1));transform-origin:50% 88%;will-change:transform}
.elfo-v3-visual{position:absolute;inset:0;transform-origin:50% 92%;will-change:transform}
.elfo-v3-frame-window{position:absolute;inset:0;overflow:hidden;pointer-events:none;filter:drop-shadow(0 8px 7px rgba(0,0,0,.38))}
.elfo-v3-sheet{position:absolute;top:0;left:0;display:block;width:400%;max-width:none!important;height:100%;object-fit:fill;transform:translate3d(0,0,0);transform-origin:0 0;will-change:transform;pointer-events:none;user-select:none;-webkit-user-drag:none}
.elfo-v3-character.is-moving .elfo-v3-frame-window{filter:drop-shadow(0 9px 8px rgba(0,0,0,.42))}
.elfo-v3-character.is-running .elfo-v3-frame-window{filter:drop-shadow(0 10px 10px rgba(0,0,0,.46))}
.elfo-v3-character.is-hopping .elfo-v3-visual{animation:elfoV3Hop 560ms cubic-bezier(.20,.76,.25,1)}
.elfo-v3-character.is-hopping .elfo-v3-shadow{animation:elfoV3ShadowHop 560ms cubic-bezier(.20,.76,.25,1)}

.elfo-v3-puller{position:absolute;z-index:35;width:clamp(150px,15.5vw,238px);height:auto;display:none;opacity:0;pointer-events:none;filter:drop-shadow(0 14px 11px rgba(0,0,0,.44));transform-origin:81.5% 8.5%;will-change:left,top,transform,opacity}
#elfoIntroV3.is-pulling .elfo-v3-puller{display:block}
.elfo-v3-hint{position:absolute;z-index:16;left:50%;bottom:20px;transform:translateX(-50%);color:rgba(238,240,241,.61);font:650 11px/1.4 system-ui,sans-serif;letter-spacing:.025em;text-shadow:0 2px 9px rgba(0,0,0,.82);pointer-events:none;opacity:0;animation:elfoV3HintIn .7s 1s ease forwards;transition:opacity 220ms ease}
#elfoIntroV3.is-sequencing .elfo-v3-hint{opacity:0!important}

@keyframes elfoV3Hop{0%{transform:translateY(0) scale(1)}16%{transform:translateY(3px) scale(1.04,.94)}46%{transform:translateY(-31px) scale(.98,1.025)}72%{transform:translateY(-8px) scale(1.01,.99)}100%{transform:translateY(0) scale(1)}}
@keyframes elfoV3ShadowHop{0%,100%{transform:scaleX(1);opacity:.56}48%{transform:scaleX(.60);opacity:.25}}
@keyframes elfoV3HintIn{from{opacity:0;transform:translate(-50%,7px)}to{opacity:.66;transform:translate(-50%,0)}}
@media(max-width:700px){.elfo-v3-character{width:clamp(92px,24vw,124px)}.elfo-v3-puller{width:clamp(142px,39vw,195px)}.elfo-v3-brand{top:15px;left:15px;font-size:8px}.elfo-v3-hint{bottom:13px;font-size:10px}}

EOF_CSS

cat > "$ROOT/frontend/elfo-intro-v3.js" <<'EOF_JS'
(() => {
  'use strict';
  const root=document.getElementById('elfoIntroV3'); if(!root)return;
  const leftPanel=root.querySelector('.elfo-v3-left');
  const rightPanel=root.querySelector('.elfo-v3-right');
  const actor=root.querySelector('#elfoV3Character');
  const flip=actor.querySelector('.elfo-v3-flip');
  const sheet=actor.querySelector('.elfo-v3-sheet');
  const shadow=actor.querySelector('.elfo-v3-shadow');
  const puller=root.querySelector('#elfoV3Puller');
  const visual=actor.querySelector('.elfo-v3-visual');
  document.documentElement.classList.add('elfo-intro-active');

  const WALK_FRAMES=[0,1,2,3];
  const FRAME_DISTANCE=13.5;
  const BASE_ART_FACES_LEFT=true;
  let state='roam',x=Math.max(20,innerWidth*.11),y=0,vx=0,targetX=Math.max(20,innerWidth*.78),autoDir=1;
  let pointerX=targetX,pointerSeen=false,lastPointerAt=0,lastTime=performance.now(),strideDistance=0,walkIndex=0,currentFrame=-1,lastHopAt=0,sequenceToken=0;
  const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
  const moveToward=(v,t,d)=>v<t?Math.min(v+d,t):v>t?Math.max(v-d,t):t;
  const easeInOut=t=>t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;
  const easeOutCubic=t=>1-Math.pow(1-t,3);

  function actorSize(){const r=actor.getBoundingClientRect();return{w:r.width||125,h:r.height||167}}
  function groundY(){const{h}=actorSize();return innerHeight-h-Math.max(14,innerHeight*.025)}
  function setFrame(frame){frame=clamp(frame|0,0,3);if(frame===currentFrame)return;currentFrame=frame;sheet.style.transform=`translate3d(${-frame*25}%,0,0)`}
  function setFacing(dir){if(Math.abs(dir)<.001)return;const face=BASE_ART_FACES_LEFT?(dir>0?-1:1):(dir>0?1:-1);flip.style.setProperty('--elfo-face',String(face))}
  function setPos(nx,ny){x=nx;y=ny;actor.style.transform=`translate3d(${x.toFixed(2)}px,${y.toFixed(2)}px,0)`}
  function stopPose(){strideDistance=0;walkIndex=0;setFrame(0);shadow.style.transform='scaleX(1)';shadow.style.opacity='.56'}
  function setMoving(moving,running=false){actor.classList.toggle('is-moving',moving);actor.classList.toggle('is-running',running&&moving);if(!moving)stopPose()}
  function advanceWalk(distance,speed){strideDistance+=Math.abs(distance);while(strideDistance>=FRAME_DISTANCE){strideDistance-=FRAME_DISTANCE;walkIndex=(walkIndex+1)%WALK_FRAMES.length;setFrame(WALK_FRAMES[walkIndex])}const intensity=clamp(Math.abs(speed)/240,0,1);shadow.style.transform=`scaleX(${(1-intensity*.10).toFixed(3)})`;shadow.style.opacity=String(.56-intensity*.08)}
  function hop(){const now=performance.now();if(state!=='roam'||now-lastHopAt<950)return;lastHopAt=now;actor.classList.remove('is-hopping');void actor.offsetWidth;actor.classList.add('is-hopping');setTimeout(()=>actor.classList.remove('is-hopping'),590)}

  function updateRoam(now){
    const dt=Math.min(.034,Math.max(.001,(now-lastTime)/1000));lastTime=now;
    const{w}=actorSize();y=groundY();
    const pointerActive=pointerSeen&&(now-lastPointerAt<4600);
    const leftBound=Math.max(14,innerWidth*.055),rightBound=Math.max(leftBound,innerWidth-w-Math.max(14,innerWidth*.055));
    if(pointerActive) targetX=clamp(pointerX-w*.5,10,innerWidth-w-10);
    else if(Math.abs(targetX-x)<12||targetX<leftBound-1||targetX>rightBound+1){autoDir*=-1;targetX=autoDir>0?rightBound:leftBound}
    const dx=targetX-x,deadZone=pointerActive?5.5:8;let desiredV=0;
    if(Math.abs(dx)>deadZone){const maxSpeed=pointerActive?235:105,minSpeed=pointerActive?72:58;desiredV=Math.sign(dx)*clamp(minSpeed+Math.abs(dx)*1.45,minSpeed,maxSpeed)}
    const accelerating=Math.sign(desiredV)===Math.sign(vx)&&Math.abs(desiredV)>Math.abs(vx);
    vx=moveToward(vx,desiredV,(desiredV===0?920:(accelerating?620:1050))*dt);
    let delta=vx*dt;if(desiredV!==0&&Math.sign(delta)===Math.sign(dx)&&Math.abs(delta)>Math.abs(dx)){delta=dx;vx=0}
    x=clamp(x+delta,8,innerWidth-w-8);
    const moving=Math.abs(vx)>9&&Math.abs(delta)>.05;
    if(moving){setFacing(vx);setMoving(true,Math.abs(vx)>180);advanceWalk(delta,vx)}else setMoving(false);
    setPos(x,y);
  }
  function loop(now){if(state==='roam')updateRoam(now);requestAnimationFrame(loop)}
  function animate(ms,update,easing=t=>t){return new Promise(resolve=>{const start=performance.now();const tick=now=>{const raw=clamp((now-start)/ms,0,1);update(easing(raw),raw);raw<1?requestAnimationFrame(tick):resolve()};requestAnimationFrame(tick)})}

  async function walkTo(destX,speed=300){
    const startX=x,distance=destX-startX,absDistance=Math.abs(distance);if(absDistance<2)return;
    setFacing(distance);actor.classList.add('is-moving','is-running');const duration=clamp(absDistance/speed*1000,260,1450);let prev=startX;
    await animate(duration,p=>{const nx=startX+distance*p,step=nx-prev;prev=nx;x=nx;y=groundY();advanceWalk(step,Math.sign(distance)*speed);setPos(x,y)},t=>t);
    vx=0;setMoving(false);
  }
  async function leapToZipper(token){
    const{w}=actorSize(),sx=x,sy=y,ex=innerWidth/2-w/2,ey=Math.max(8,innerHeight*.018);
    await animate(145,p=>{if(token!==sequenceToken)return;visual.style.transform=`translateY(${5*p}px) scale(${1+.045*p},${1-.07*p})`},easeOutCubic);
    visual.style.transform='';setFrame(2);
    await animate(900,(p,raw)=>{if(token!==sequenceToken)return;const e=easeInOut(p);x=sx+(ex-sx)*e;const linearY=sy+(ey-sy)*e,arc=Math.sin(Math.PI*raw)*Math.min(150,innerHeight*.18);y=linearY-arc;setPos(x,y);const lift=Math.sin(Math.PI*raw);shadow.style.transform=`scaleX(${1-lift*.52})`;shadow.style.opacity=String(.56-lift*.38);actor.style.opacity=String(1-Math.max(0,raw-.84)*6.2)},easeOutCubic);
  }
  function updatePanelCut(sliderY,gapPx){const yy=Math.round(sliderY),gap=Math.round(gapPx);leftPanel.style.clipPath=`polygon(0 0,calc(50% - ${gap}px) 0,50% ${yy}px,50% 100%,0 100%)`;rightPanel.style.clipPath=`polygon(calc(50% + ${gap}px) 0,100% 0,100% 100%,50% 100%,50% ${yy}px)`;root.style.setProperty('--zip-y',`${yy}px`)}
  async function pullZipper(token){
    root.classList.add('is-pulling');actor.style.opacity='0';puller.style.opacity='1';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
    const rect=puller.getBoundingClientRect(),pw=rect.width||200,ph=rect.height||pw,startY=Math.max(-6,innerHeight*.002),endY=Math.max(170,innerHeight-ph*.72-22),anchorX=innerWidth/2-pw*.815;
    updatePanelCut(0,0);
    await animate(1875,(p,raw)=>{if(token!==sequenceToken)return;const e=easeInOut(p),py=startY+(endY-startY)*e,sliderY=clamp(py+pw*.12,0,innerHeight),gap=Math.sin(e*Math.PI/2)*Math.min(168,innerWidth*.115);puller.style.left=`${anchorX}px`;puller.style.top=`${py}px`;puller.style.transform=`rotate(${Math.sin(raw*Math.PI*6)*1.15}deg)`;updatePanelCut(sliderY,gap)},t=>t);
  }
  async function beginSequence(){
    if(state!=='roam')return;state='sequence';root.classList.add('is-sequencing');pointerSeen=false;vx=0;const token=++sequenceToken,{w}=actorSize();
    await walkTo(innerWidth/2-w/2,335);if(token!==sequenceToken)return;await new Promise(r=>setTimeout(r,90));await leapToZipper(token);if(token!==sequenceToken)return;await new Promise(r=>setTimeout(r,60));await pullZipper(token);if(token!==sequenceToken)return;
    root.classList.add('is-opening');puller.style.transition='opacity 300ms ease,transform 520ms cubic-bezier(.2,.8,.2,1)';puller.style.opacity='0';puller.style.transform+=' translateY(30px) scale(.94)';await new Promise(r=>setTimeout(r,1080));document.documentElement.classList.remove('elfo-intro-active');root.hidden=true;state='done';
  }

  document.addEventListener('pointermove',e=>{if(state!=='roam')return;pointerSeen=true;pointerX=e.clientX;lastPointerAt=performance.now()},{passive:true});
  actor.addEventListener('pointerenter',hop);actor.addEventListener('click',beginSequence);actor.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();beginSequence()}});
  addEventListener('resize',()=>{if(state!=='roam')return;const{w}=actorSize();x=clamp(x,8,innerWidth-w-8);y=groundY();setPos(x,y)});
  requestAnimationFrame(()=>{y=groundY();setFrame(0);setFacing(1);setPos(x,y);requestAnimationFrame(loop)});
})();

EOF_JS

cat > "$ROOT/.elfo_v3_patcher.py" <<'EOF_PATCH'
from pathlib import Path
import re
p=Path('frontend/index.html')
s=p.read_text(encoding='utf-8')
for version in ('V2','V3'):
    for kind in ('CSS','HTML','JS'):
        s=re.sub(rf'\s*<!-- ELFO_INTRO_{version}_{kind}_START -->.*?<!-- ELFO_INTRO_{version}_{kind}_END -->\s*','\n',s,flags=re.S|re.I)
for kind in ('CSS','HTML','JS'):
    s=re.sub(rf'\s*<!-- DENIM_ELFO_INTRO_{kind}_START -->.*?<!-- DENIM_ELFO_INTRO_{kind}_END -->\s*','\n',s,flags=re.S|re.I)
s=re.sub(r'''\s*<link[^>]+href=["']/static/(?:denim-intro|elfo-intro-v2|elfo-intro-v3)\.css[^"']*["'][^>]*>\s*''','\n',s,flags=re.I)
s=re.sub(r'''\s*<script[^>]+src=["']/static/(?:denim-intro|elfo-intro-v2|elfo-intro-v3)\.js[^"']*["'][^>]*>\s*</script>\s*''','\n',s,flags=re.I)
css_tag='''\n    <!-- ELFO_INTRO_V3_CSS_START -->\n    <link rel="stylesheet" href="/static/elfo-intro-v3.css?v=3">\n    <!-- ELFO_INTRO_V3_CSS_END -->\n'''
html_block='''    <!-- ELFO_INTRO_V3_HTML_START -->
    <div id="elfoIntroV3" aria-label="Royal Jeans cinematic denim intro">
        <div class="elfo-v3-reveal" aria-hidden="true"></div>
        <div class="elfo-v3-panel elfo-v3-left" aria-hidden="true"></div>
        <div class="elfo-v3-panel elfo-v3-right" aria-hidden="true"></div>
        <div class="elfo-v3-open-light" aria-hidden="true"></div>
        <div class="elfo-v3-vignette" aria-hidden="true"></div>
        <div class="elfo-v3-brand" aria-hidden="true">ROYAL JEANS / DENIM LAB</div>
        <button id="elfoV3Character" class="elfo-v3-character" type="button" aria-label="الفو؛ برای باز کردن برنامه کلیک کنید">
            <span class="elfo-v3-shadow" aria-hidden="true"></span>
            <span class="elfo-v3-flip" aria-hidden="true"><span class="elfo-v3-visual"><span class="elfo-v3-frame-window"><img class="elfo-v3-sheet" src="/static/elfo-walk-v3.png?v=3" alt="" draggable="false"></span></span></span>
        </button>
        <img id="elfoV3Puller" class="elfo-v3-puller" src="/static/elfo-puller-v3.png?v=3" alt="" draggable="false" aria-hidden="true">
        <div class="elfo-v3-hint" aria-hidden="true">الفو موس رو دنبال می‌کنه · روش کلیک کن</div>
    </div>
    <!-- ELFO_INTRO_V3_HTML_END -->'''
js_tag='''\n    <!-- ELFO_INTRO_V3_JS_START -->\n    <script src="/static/elfo-intro-v3.js?v=3"></script>\n    <!-- ELFO_INTRO_V3_JS_END -->\n'''
if '</head>' not in s or '</body>' not in s: raise SystemExit('ساختار index.html معتبر نیست')
s=s.replace('</head>',css_tag+'\n</head>',1)
body=re.search(r'<body[^>]*>',s,flags=re.I)
if not body: raise SystemExit('تگ body پیدا نشد')
s=s[:body.end()]+'\n'+html_block+'\n'+s[body.end():]
s=s.replace('</body>',js_tag+'\n</body>',1)
p.write_text(s,encoding='utf-8')
print('✅ index.html به Elfo Intro V3 متصل شد')

EOF_PATCH
cd "$ROOT"
python "$ROOT/.elfo_v3_patcher.py"
rm -f "$ROOT/.elfo_v3_patcher.py"

