B64_DENIM_ZIP_V3
base64 -d "$ROOT/frontend/denim-zip-v3.png.b64" > "$ROOT/frontend/denim-zip-v3.png"
rm -f "$ROOT/frontend/denim-zip-v3.png.b64"


if command -v node >/dev/null 2>&1; then
  node --check "$ROOT/frontend/elfo-intro-v3.js"
  echo "✅ JavaScript syntax OK"
fi
python - <<'CHECKPY'
from pathlib import Path
files={'frontend/elfo-walk-v3.png':100000,'frontend/elfo-puller-v3.png':100000,'frontend/denim-zip-v3.png':500000}
for name,min_size in files.items():
    p=Path(name)
    if not p.exists() or p.stat().st_size<min_size: raise SystemExit(f'asset خراب یا ناقص است: {name}')
html=Path('frontend/index.html').read_text(encoding='utf-8')
for token in ('elfoIntroV3','elfo-intro-v3.css','elfo-intro-v3.js','elfo-walk-v3.png'):
    if token not in html: raise SystemExit(f'patch ناقص است: {token}')
print('✅ Asset + HTML integrity OK')
CHECKPY
if [[ "${ELFO_NO_RESTART:-0}" == "1" ]]; then
  echo "🔥 ELFO INTRO V3 نصب شد. (restart skipped)"
  exit 0
fi
if command -v fuser >/dev/null 2>&1; then
  fuser -k 8000/tcp >/dev/null 2>&1 || true
else
  pkill -f "uvicorn api:app.*--port 8000" >/dev/null 2>&1 || true
fi
sleep 0.7
UVICORN="$ROOT/.venv/bin/uvicorn"
if [[ ! -x "$UVICORN" ]]; then UVICORN="$(command -v uvicorn || true)"; fi
if [[ -z "$UVICORN" ]]; then
  echo "⚠️ نصب انجام شد ولی uvicorn پیدا نشد؛ سرور را دستی اجرا کن."
  exit 0
fi
(
  cd "$ROOT/backend"
  nohup "$UVICORN" api:app --host 0.0.0.0 --port 8000 > "$ROOT/uvicorn.log" 2>&1 &
  echo $! > "$ROOT/uvicorn.pid"
)
OK=0
for i in {1..40}; do
  if curl -fsS http://127.0.0.1:8000/ 2>/dev/null | grep -q "elfoIntroV3"; then OK=1; break; fi
  sleep 0.35
done
if [[ "$OK" != "1" ]]; then
  echo "❌ سرور بالا نیامد یا نسخه V3 سرو نشد. آخرین لاگ:"
  tail -n 80 "$ROOT/uvicorn.log" || true
  exit 1
fi
echo
echo "🔥 ELFO MOTION V3 نصب شد."
echo "✅ جهت راه‌رفتن اصلاح شد؛ حرکت به راست دیگر برعکس نیست."
echo "✅ پاها با فریم‌های واقعی و بر اساس مسافت طی‌شده Sync می‌شوند، نه با تکان‌دادن عکس."
echo "✅ شتاب، کاهش سرعت، ایستادن و Run طبیعی‌تر شد."
echo "✅ زیپ و جین واقعی حفظ شد و بازشدن پارچه نرم‌تر است."
echo "✅ سرور روی پورت 8000 بالا آمد."
echo
echo "➡️ PORTS → 8000 → Open in Browser"
echo "➡️ اگر تب قبلی باز است Ctrl+Shift+R بزن."
